      matrix.m00 = m00;
      matrix.m10 = m10;
      matrix.m20 = m20;
      matrix.m30 = m30;
      matrix.m01 = m01;
      matrix.m11 = m11;
      matrix.m21 = m21;
      matrix.m31 = m31;
      matrix.m02 = m02;
      matrix.m12 = m12;
      matrix.m22 = m22;
      matrix.m32 = m32;
      matrix.m03 = m03;
      matrix.m13 = m13;
