    this._writer.write2RawDouble(layout.minLimits);
    this._writer.write2RawDouble(layout.minLimits);
    this._writer.write3BitDouble(layout.insertionBasePoint);
    this._writer.write3BitDouble(layout.xAxis);
    this._writer.write3BitDouble(layout.yAxis);
